      "description": "在执行器变更后更新相关状态",
      "description_en": "Update dependent state after actuator changes"
    },
    {
      "action_name": "auto-format_bounds",
      "description": "格式化搜索边界",
      "description_en": "Format the search bounds"
    },
    {
      "action_name": "auto-set_algorithm",
      "description": "选择优化算法",
      "description_en": "Set the optimization algorithm"
    },
    {
      "action_name": "auto-ini_model",
      "description": "初始化优化模型",
      "description_en": "Initialize the optimization model"
    },
    {
      "action_name": "auto-do_save",
      "description": "执行保存准备或保存操作",
      "description_en": "Prepare for saving or perform saving"
    },
    {
      "action_name": "auto-ini_saver",
      "description": "初始化保存器",
      "description_en": "Initialize the saver"
    },
    {
      "action_name": "auto-recursive_enable",
      "description": "递归启用或禁用设置项",
      "description_en": "Recursively enable or disable settings"
    },
    {
      "action_name": "auto-enable_settings_run",
      "description": "启用或禁用运行相关设置",
      "description_en": "Enable or disable run-related settings"
    },
    {
      "action_name": "auto-stop_algo",
      "description": "停止优化算法",
      "description_en": "Stop the optimization algorithm"
    },
    {
      "action_name": "auto-restart_algo",
      "description": "重启优化算法",
      "description_en": "Restart the optimization algorithm"
    },
    {
      "action_name": "auto-check_create_save_node",
      "description": "检查或创建保存节点",
      "description_en": "Check or create a save node"
    },
    {
      "action_name": "auto-ini_optimization_runner",
      "description": "初始化优化运行器",
      "description_en": "Initialize the optimization runner"
    },
    {
      "action_name": "auto-clean_h5_temp",
      "description": "清理临时 HDF5 数据",
      "description_en": "Clean temporary HDF5 data"
    },
    {
      "action_name": "auto-optimization_done",
      "description": "处理优化完成后的操作",
      "description_en": "Handle post-optimization completion tasks"
    },
    {
      "action_name": "auto-do_live_plot",
      "description": "更新实时优化曲线",
      "description_en": "Update the live optimization plot"
    },
    {
      "action_name": "auto-update_data_plot",
      "description": "更新数据图显示",
      "description_en": "Update the data plot display"
    },
    {
      "action_name": "auto-enable_controls_opti",
      "description": "启用或禁用优化控制项",
      "description_en": "Enable or disable optimization controls"
    },
    {
      "action_name": "auto-run_optimization",
      "description": "启动优化运行",
      "description_en": "Run the optimization"
    },
    {
      "action_name": "auto-thread_status",
      "description": "处理线程状态更新",
      "description_en": "Handle thread status updates"
    }
  ]
}

